#ifndef MYLIB_MINIMAP_GLSL
#define MYLIB_MINIMAP_GLSL

// Shared by terrain (capture) and the post effect (memory and display). Needs Globals.
// Faces of the extra top element added to the block models (y = 1.25/16 inside the block) are drawn
// by terrain.vsh into a capture square in the top-right corner: one pixel per block, north up,
// centered on the camera's block. The post effect copies them into a persistent memory where each
// texel is a block (world x and z modulo MAP_MEMORY), then draws the map over the capture square.
const float MAP_MARK = 1.25 / 16.0;
const int MAP_BLOCKS = 128;     // blocks across the capture and the map
const int MAP_MEMORY = 256;     // texels across the persistent memory (a power of two)
const int MAP_MARGIN = 16;      // pixels between the map and the screen corner
const int MAP_SCALE = 2;        // screen pixels per block on the displayed map
const float MAP_TAG = 0.5;      // alpha written by map faces in minecraft:main

bool isMapVertex(vec3 position) {
    return abs(fract(position.y) - MAP_MARK) < 1.0e-4;
}

// Bottom-left pixel of the capture square, counted from the bottom-left of the screen.
ivec2 captureOrigin() {
    return ivec2(ScreenSize) - ivec2(MAP_MARGIN + MAP_BLOCKS);
}

// Pixel of the block at (x, z) from the camera's block.
ivec2 capturePixel(ivec2 rel) {
    return captureOrigin() + ivec2(MAP_BLOCKS / 2 + rel.x, MAP_BLOCKS / 2 - 1 - rel.y);
}

// Texel of the memory that holds a block, from its world x and z (wraps around).
ivec2 memoryTexel(ivec2 world) {
    return world & (MAP_MEMORY - 1);
}

#endif

