#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <mylib:minimap.glsl>

// One texel per block of the memory: take the block from this frame's capture when it is there,
// keep what the memory had otherwise.
uniform sampler2D MainSampler;
uniform sampler2D HistorySampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    ivec2 texel = ivec2(texCoord * float(MAP_MEMORY));
    // The block this texel stands for: the one nearest to the camera among those that wrap onto it.
    ivec2 rel = ((texel - CameraBlockPos.xz + MAP_MEMORY / 2) & (MAP_MEMORY - 1)) - MAP_MEMORY / 2;
    fragColor = texelFetch(HistorySampler, texel, 0);
    if (all(greaterThanEqual(rel, ivec2(-MAP_BLOCKS / 2))) && all(lessThan(rel, ivec2(MAP_BLOCKS / 2)))) {
        vec4 captured = texelFetch(MainSampler, capturePixel(rel), 0);
        if (abs(captured.a - MAP_TAG) < 0.05) {
            fragColor = vec4(captured.rgb, 1.0);
        }
    }
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Copy with alpha: in the memory, alpha 0 means "never seen".
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = texture(InSampler, texCoord);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <mylib:minimap.glsl>

// Draw the map from the memory over the capture square, MAP_SCALE pixels per block, north up.
uniform sampler2D MainSampler;
uniform sampler2D MapSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    ivec2 pixel = ivec2(texCoord * ScreenSize);
    fragColor = vec4(texelFetch(MainSampler, pixel, 0).rgb, 1.0);

    int size = MAP_BLOCKS * MAP_SCALE;
    ivec2 local = pixel - (ivec2(ScreenSize) - ivec2(MAP_MARGIN + size));
    if (any(lessThan(local, ivec2(-1))) || any(greaterThan(local, ivec2(size)))) {
        return;
    }
    if (any(lessThan(local, ivec2(0))) || any(greaterThanEqual(local, ivec2(size)))) {
        fragColor = vec4(1.0);   // border
        return;
    }
    ivec2 block = local / MAP_SCALE;
    ivec2 rel = ivec2(block.x - MAP_BLOCKS / 2, MAP_BLOCKS / 2 - 1 - block.y);
    vec4 memory = texelFetch(MapSampler, memoryTexel(CameraBlockPos.xz + rel), 0);
    fragColor = memory.a > 0.5 ? vec4(memory.rgb, 1.0) : vec4(0.12, 0.12, 0.12, 1.0);   // dark grey: never seen
    if (all(lessThanEqual(abs(rel), ivec2(1)))) {
        fragColor = vec4(1.0, 0.0, 0.0, 1.0);   // the camera
    }
}
